import sys
import xml.etree.ElementTree as ET
import sqlite3
import json

def parse_xml(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        db_path = root.find('database').get('path')
        query = root.find('query')
        table = query.get('table')
        column = query.get('column')
        value = query.get('value')
        return db_path, table, column, value
    except (ET.ParseError, AttributeError, FileNotFoundError):
        print("ERROR", file=sys.stderr)
        sys.exit(1)

def get_column_names(cursor):
    cursor.description = None
    cursor.execute("PRAGMA table_info(?)".format(table))
    columns = [col[1] for col in cursor.description]
    return columns

def format_row(row, columns):
    formatted = {}
    for i, col in enumerate(columns):
        value = row[i]
        if value is None:
            formatted[col] = None
        elif isinstance(value, (int, float)):
            formatted[col] = float(value) if isinstance(value, float) else int(value)
        else:
            formatted[col] = str(value)
    return formatted

def main():
    if len(sys.argv) != 2:
        print("ERROR", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    db_path, table, column, value = parse_xml(xml_path)

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute("SELECT * FROM {} WHERE {} = ?".format(table, column), (value,))
        columns = get_column_names(cursor)
        rows = cursor.fetchall()

        for row in rows:
            print(json.dumps(format_row(row, columns)))

    except sqlite3.Error:
        print("ERROR", file=sys.stderr)
        sys.exit(1)
    finally:
        if 'conn' in locals():
            conn.close()

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import sqlite3
import json

def parse_xml(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        db_path = None
        query_params = None

        for elem in root:
            if elem.tag == 'database':
                db_path = elem.get('path')
            elif elem.tag == 'query':
                query_params = {
                    'table': elem.get('table'),
                    'column': elem.get('column'),
                    'value': elem.get('value')
                }
        return db_path, query_params
    except Exception as e:
        print(f"ERROR: Failed to parse XML file: {e}", file=sys.stderr)
        sys.exit(1)

def execute_query(db_path, query_params):
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        table = query_params['table']
        column = query_params['column']
        value = query_params['value']

        cursor.execute(f"SELECT * FROM {table} WHERE {column} = ?", (value,))
        rows = cursor.fetchall()

        column_names = [desc[0] for desc in cursor.description]

        for row in rows:
            print(json.dumps(dict(zip(column_names, row))))

        conn.close()
    except Exception as e:
        print(f"ERROR: Failed to execute query: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("ERROR: Usage: python query_tool.py <xml_config_file>", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    db_path, query_params = parse_xml(xml_path)

    if db_path is None or query_params is None:
        sys.exit(1)

    execute_query(db_path, query_params)
